function firstWord(words, note) {
  const budget = new Map();
  for (const ch of note) {
    budget.set(ch, (budget.get(ch) ?? 0) + 1);
  }

  const canForm = (word) => {
    const used = new Map();
    for (const ch of word) {
      const spent = (used.get(ch) ?? 0) + 1;
      if (spent > (budget.get(ch) ?? 0)) return false; // over budget → bail
      used.set(ch, spent);
    }
    return true;
  };

  for (const word of words) {
    if (canForm(word)) return word; // first success wins
  }
  return '-';
}

