function buildableRobots(parts, requiredStr) {
  const required = requiredStr.split(',');

  const partsByRobot = new Map(); // robot → Set of distinct parts
  for (const entry of parts) {
    const [robot, part] = entry.split('_');
    if (!partsByRobot.has(robot)) partsByRobot.set(robot, new Set());
    partsByRobot.get(robot).add(part);
  }

  const result = [];
  for (const [robot, owned] of partsByRobot) { // insertion order = first appearance
    if (required.every((part) => owned.has(part))) {
      result.push(robot);
    }
  }
  return result;
}

