function shopping(products, list) {
  const departmentOf = new Map(products); // [product, department] pairs → Map

  let naiveVisits = 0;
  let lastDepartment = ''; // no real department is '' → first item always counts
  const distinct = new Set();

  for (const product of list) {
    const dept = departmentOf.get(product);
    if (dept !== lastDepartment) naiveVisits++; // transition = new visit
    lastDepartment = dept;
    distinct.add(dept);                          // Set does the optimal side
  }
  return naiveVisits - distinct.size;
}

