  ['Blueberries', 'Produce'], ['Iceberg Lettuce', 'Produce'],
  ['Flour', 'Pantry'], ['Pasta', 'Pantry'],
  ['Milk', 'Dairy'], ['Cheese', 'Dairy'],
];
