function carpool(roads, starts, people) {
  const nextStop = new Map();
  for (const [origin, dest, duration] of roads) {
    nextStop.set(origin, { dest, duration: Number(duration) }); // parse NOW
  }

  // each car's location → arrival time, start included at t=0
  const arrivalsPerCar = starts.map((start) => {
    const arrivals = new Map([[start, 0]]);
    let location = start, time = 0;
    while (nextStop.has(location)) {
      const { dest, duration } = nextStop.get(location);
      time += duration;
      location = dest;
      if (!arrivals.has(location)) arrivals.set(location, time);
    }
    return arrivals;
  });

  const riders = starts.map(() => []);
  for (const [name, location] of people) {
    let bestCar = -1, bestTime = Infinity;
    arrivalsPerCar.forEach((arrivals, carIndex) => {
      const t = arrivals.get(location);
      if (t !== undefined && t < bestTime) { bestTime = t; bestCar = carIndex; }
