function fulfillableOrders(inventory, orders) {
  const stock = new Map();
  for (const entry of inventory) {
    const [sku, qty] = entry.split(':');
    stock.set(sku, (stock.get(sku) ?? 0) + Number(qty)); // parse at boundary
